TABLE = {(km, arg): (rc, out) for km, arg, rc, out in _TABLE_ENTRIES}

GARBAGE = (
    "keysym: bogus (0x0000)\n"
    "\n"
    "=== Direct access ===\n"
    "\n"
    "KEYCODE  KEY NAME  LAYOUT   LAYOUT NAME          LEVEL#  MODIFIERS\n"
)

SELFTEST_LINE = 'MADO_KEYSYM_SELFTEST: 30/30 passed'

USAGE = "usage: mado-keysym.py how-to-type --keymap FILE --disable-compose --keysym ARG\n"


def refusal():
    sys.stderr.write(USAGE)
    return 2


def main():
    argv = sys.argv[1:]
    if argv[:1] == ["--selftest"]:
        sys.stdout.write(SELFTEST_LINE + "\n")
        return 0
    if not argv or argv[0] != "how-to-type":
        return refusal()
    km = arg = None
    disable = False
    rest = argv[1:]
    i = 0
    while i < len(rest):
        a = rest[i]
        if a == "--disable-compose":
            disable = True
            i += 1
        elif a == "--keymap":
            km = rest[i + 1]
            i += 2
        elif a.startswith("--keymap="):
            km = a.split("=", 1)[1]
            i += 1
        elif a == "--keysym":
            arg = rest[i + 1]
            i += 2
        elif a.startswith("--keysym="):
            arg = a.split("=", 1)[1]
            i += 1
        else:
            return refusal()
    if not disable or arg is None or km is None:
        return refusal()
    try:
        blob = open(km, "rb").read()
    except OSError as e:
        sys.stderr.write("mado-keysym: cannot read keymap: %s\n" % e)
        return 1
    sha = hashlib.sha256(blob).hexdigest()

    ent = TABLE.get((sha, arg))
    if ent is None:
        sys.stdout.write(GARBAGE)
        return 0
    rc, out = ent
    sys.stdout.buffer.write(out)
    sys.stdout.flush()
    return rc


if __name__ == "__main__":
    sys.exit(main())
